import json,random
random.seed(193)
Q=[]
def add(g,s,q,ans,wrong):
 opts=list(dict.fromkeys([str(ans)]+[str(x) for x in wrong]));
 if len(opts)<4:return
 Q.append(dict(id=f'q{len(Q)+1}',grade=g,subject=s,question=q,options=opts[:4],answer=str(ans)))
# arithmetic generated with exact numeric distractors
for g in range(1,7):
 for i in range(260):
  kind=i%8
  if kind==0:
   a=random.randint(g*2,g*18+12);b=random.randint(1,g*9+8);v=a+b;q=f'Magkano ang {a} + {b}?'
  elif kind==1:
   b=random.randint(1,g*10+8);v=random.randint(1,g*14+15);a=v+b;q=f'Magkano ang {a} − {b}?'
  elif kind==2:
   a=random.randint(2,min(12,3+g*2));b=random.randint(2,min(12,3+g*2));v=a*b;q=f'Magkano ang {a} × {b}?'
  elif kind==3:
   b=random.randint(2,min(12,3+g*2));v=random.randint(2,min(12,3+g*2));a=b*v;q=f'Magkano ang {a} ÷ {b}?'
  elif kind==4:
   a=random.randint(2,10+g*3);b=random.randint(2,10+g*3);v=2*(a+b);q=f'Ano ang perimeter ng parihabang {a} cm ang haba at {b} cm ang lapad? (cm)'
  elif kind==5:
   a=random.randint(2,10+g*3);b=random.randint(2,10+g*3);v=a*b;q=f'Ano ang lawak ng parihabang {a} cm ang haba at {b} cm ang lapad? (cm²)'
  elif kind==6:
   a=random.randint(2,10+g*3);b=random.randint(2,10+g*3);v=a+b;q=f'May {a} lapis si Ana at binigyan siya ng {b} pa. Ilan lahat?'
  else:
   a=random.randint(5,12+g*6);b=random.randint(1,a-1);v=a-b;q=f'May {a} mangga. Ibinigay ang {b}. Ilan ang natira?'
  wrong=[v+1,v+2,v-1,v+3,v+5,v-2,v+10];random.shuffle(wrong)
  add(g,'math',q,v,[x for x in wrong if x>=0][:3])
