# exact wording variants yield distinct prompts, no duplicate question within a subject-grade
prefixes=['','Piliin ang tamang sagot: ','Subukin ang iyong kaalaman! ','Para sa checkpoint na ito: ','Hamon sa pagkatuto: ','Pag-isipan nang mabuti: ','Quiz challenge: ','Ano ang iyong sagot? ']
for g in range(1,7):
 for s,items in DATA.items():
  for j,(q,a,w) in enumerate(items):
   for k in range(4):
    # Same factual target can reappear in later rounds with rephrasing; avoid claiming unlimited unique concepts.
    add(g,s,prefixes[(k+g+j)%len(prefixes)]+q,a,w)
# shuffle answer options deterministically and set index
seen=set();unique=[]
for item in Q:
 key=(item['grade'],item['subject'],item['question'])
 if key in seen:continue
 seen.add(key)
 opts=item.pop('options');random.shuffle(opts);item['choices']=opts;item['correct']=opts.index(item.pop('answer'));unique.append(item)
with open('/mnt/data/karera-ng-talino-3d/questions.js','w') as f:
 f.write('// EDITABLE QUESTION BANK. Each item: grade, subject, question, choices, correct (0-3).\n')
 f.write('// To add your own: QUESTION_BANK.push({id:"custom1",grade:4,subject:"science",question:"...",choices:["A","B","C","D"],correct:0});\n')
 f.write('window.QUESTION_BANK = '+json.dumps(unique,ensure_ascii=False,separators=(',',':'))+';\n')
print(len(unique),{s:sum(x['subject']==s for x in unique) for s in ['math',*DATA]})
